//! 🧪️ An actual typed metadata copy restores original source pointers and returns every partial alias under the same caller.
use super::*;
use semio_framework_plugin_decl_emission::{ActionMeta,OriginalActionMetaCopy as Copy};
use semio_framework_value::retained_clone::RetainedCloneClose;
#[track_caller]
fn native<T>(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,g:RetainedCloneGrant,f:impl FnOnce(&mut StepContext<'_>)->Result<T,OriginalTurnFailure>)->T{let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn_with_decoder(g,decoder,f));let p=caller.receipt();assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));result.unwrap()}
#[test]
fn original_action_metadata_copy_restores_the_exact_source_and_closes_partial_aliases(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:32768,maximum_capacity_bytes:16<<20,maximum_release_bytes:16<<20,maximum_depth:4096};
 for cut in law["cancelAfter"].as_array().unwrap().iter().map(|v|Some(v.as_u64().unwrap()as usize)).chain([None]){let mut caller=caller();let mut decoder=OriginalJobDecodeOwner::empty();let mut view=semio_framework::ViewModel::new(semio_framework_ui_locale::Locale::En,semio_framework_ui_locale::Terminology::Native);view.active_mode_id=Some("x".repeat(law["wideTextBytes"].as_u64().unwrap()as usize));for index in 0..2{let key=law["mapKeys"][index].as_str().unwrap();view.active_utility_by_window_id.insert(key.into(),law["utilityValues"][index].as_str().unwrap().into());view.tool_run_trace_cursor_by_window_id.insert(key.into(),semio_framework_tool_run::ToolRunTraceCursor{generation:13,page:index as u32,run:23});}let text=view.active_mode_id.as_ref().unwrap().as_ptr();let maps=(view.active_utility_by_window_id.original_root_identity(),view.tool_run_trace_cursor_by_window_id.original_root_identity());let mut input=Some(ActionMeta{actor:"original source".into(),instance_id:71,view_state:Some(view)});let mut copy=None;let mut output=None;native(&mut caller,&mut decoder,g,|cx|Copy::admit(cx,&mut copy));let mut foreign=OriginalJobDecodeOwner::empty();native(&mut caller,&mut foreign,g,|cx|{assert!(copy.as_mut().unwrap().advance(&mut input,cx).is_err());Ok(())});assert!(input.is_some());for index in 0..262144{if cut==Some(index){caller.cancel().cancel_now();break}if native(&mut caller,&mut decoder,g,|cx|copy.as_mut().unwrap().advance(&mut input,cx)){break}assert!(index<262143)}if cut.is_none(){native(&mut caller,&mut decoder,g,|cx|copy.as_mut().unwrap().take_into(&mut output,cx));assert_eq!(input.as_ref().unwrap().view_state.as_ref().unwrap().active_mode_id.as_ref().unwrap().as_ptr(),text);let original=input.as_ref().unwrap().view_state.as_ref().unwrap();let received=output.as_ref().unwrap().view_state.as_ref().unwrap();assert_eq!(serde_json::to_value(original).unwrap(),serde_json::to_value(received).unwrap());assert_eq!((received.active_utility_by_window_id.original_root_identity(),received.tool_run_trace_cursor_by_window_id.original_root_identity()),maps);assert_ne!(received.active_mode_id.as_ref().unwrap().as_ptr(),text);}
  for index in 0..262144{if copy.as_ref().unwrap().terminal_is_empty(){break}let d=copy.as_ref().unwrap().close_demands().unwrap();for axis in 0..5{let mut denied=g;match axis{0=>denied.maximum_items=0,1 if d.copy_bytes>0=>denied.maximum_copy_bytes=d.copy_bytes-1,2 if d.capacity_bytes>0=>denied.maximum_capacity_bytes=d.capacity_bytes-1,3 if d.release_bytes>0=>denied.maximum_release_bytes=d.release_bytes-1,4 if d.depth>0=>denied.maximum_depth=d.depth-1,_=>continue}native(&mut caller,&mut decoder,denied,|cx|cx.with_original_retirement(|cx|copy.as_mut().unwrap().close_step(&mut input,cx)));assert_eq!(caller.receipt(),Default::default(),"metadata copy close accepted denied axis {axis} {d:?}");assert_eq!(copy.as_ref().unwrap().close_demands().unwrap(),d);}native(&mut caller,&mut decoder,g,|cx|cx.with_original_retirement(|cx|copy.as_mut().unwrap().close_step(&mut input,cx)));assert!(index<262143)}assert_eq!(input.as_ref().unwrap().view_state.as_ref().unwrap().active_mode_id.as_ref().unwrap().as_ptr(),text);native(&mut caller,&mut decoder,g,|cx|cx.with_original_retirement(|cx|{let d=Copy::release_demand();close_original_retained_step(cx,d,|_|{copy.take();Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,released_bytes:d.release_bytes,..Default::default()}))})?;Ok(())}));
  let mut close=RetainedCloneClose::default();for input in [&mut output,&mut input]{for index in 0..262144{if input.is_none()&&close.is_empty(){break}native(&mut caller,&mut decoder,g,|cx|cx.with_original_retirement(|cx|{let d=close.next_owner_demands::<ActionMeta>(input.is_some(),&None,32768)?;close_original_retained_step(cx,d,|grant|if let Some(step)=close.begin_granted(input,grant)?{Ok(step)}else{close.select(32768)?.step(grant)})?;Ok(())}));assert!(index<262143)}}for decoder in [&mut decoder,&mut foreign]{while !decoder.terminal_is_empty(){caller.turn(g,|cx|cx.with_original_retirement(|cx|{let d=decoder.retirement_demands(32768)?;close_original_retained_step(cx,d,|grant|decoder.close_step(grant))?;Ok(())})).unwrap();}}caller.retire(g);
 }
}
